318	// FromError parses a Status error or a googleapi.Error and builds an
319	// APIError, wrapping the provided error in the new APIError. It
320	// returns false if neither Status nor googleapi.Error can be parsed.
321	func FromError(err error) (*APIError, bool) {
322		return ParseError(err, true)
323	}
324	
325	// ParseError parses a Status error or a googleapi.Error and builds an
326	// APIError. If wrap is true, it wraps the error in the new APIError.
327	// It returns false if neither Status nor googleapi.Error can be parsed.
328	func ParseError(err error, wrap bool) (*APIError, bool) {
329		if err == nil {
330			return nil, false
331		}
332		ae := APIError{}
333		if wrap {
334			ae = APIError{err: err}
335		}
336		if !ae.setDetailsFromError(err) {
337			return nil, false
338		}
339		return &ae, true
340	}
