342	// parseDetails accepts a slice of interface{} that should be backed by some
343	// sort of proto.Message that can be cast to the google/rpc/error_details.proto
344	// types.
345	//
346	// This is for internal use only.
347	func parseDetails(details []interface{}) ErrDetails {
348		var ed ErrDetails
349		for _, d := range details {
350			switch d := d.(type) {
351			case *errdetails.ErrorInfo:
352				ed.ErrorInfo = d
353			case *errdetails.BadRequest:
354				ed.BadRequest = d
355			case *errdetails.PreconditionFailure:
356				ed.PreconditionFailure = d
357			case *errdetails.QuotaFailure:
358				ed.QuotaFailure = d
359			case *errdetails.RetryInfo:
360				ed.RetryInfo = d
361			case *errdetails.ResourceInfo:
362				ed.ResourceInfo = d
363			case *errdetails.RequestInfo:
364				ed.RequestInfo = d
365			case *errdetails.DebugInfo:
366				ed.DebugInfo = d
367			case *errdetails.Help:
368				ed.Help = d
369			case *errdetails.LocalizedMessage:
370				ed.LocalizedMessage = d
371			default:
372				ed.Unknown = append(ed.Unknown, d)
373			}
374		}
375	
376		return ed
377	}
