379	// parseHTTPDetails will convert the given googleapi.Error into the protobuf
380	// representation then parse the Any values that contain the error details.
381	//
382	// This is for internal use only.
383	func parseHTTPDetails(gae *googleapi.Error) ErrDetails {
384		e := &jsonerror.Error{}
385		if err := protojson.Unmarshal([]byte(gae.Body), e); err != nil {
386			// If the error body does not conform to the error schema, ignore it
387			// altogther. See https://cloud.google.com/apis/design/errors#http_mapping.
388			return ErrDetails{}
389		}
390	
391		// Coerce the Any messages into proto.Message then parse the details.
392		details := []interface{}{}
393		for _, any := range e.GetError().GetDetails() {
394			m, err := any.UnmarshalNew()
395			if err != nil {
396				// Ignore malformed Any values.
397				continue
398			}
399			details = append(details, m)
400		}
401	
402		return parseDetails(details)
403	}
