405	// HTTPCode returns the underlying HTTP response status code. This method returns
406	// `-1` if the underlying error is a [google.golang.org/grpc/status.Status]. To
407	// check gRPC error codes use [google.golang.org/grpc/status.Code].
408	func (a *APIError) HTTPCode() int {
409		if a.httpErr == nil {
410			return -1
411		}
412		return a.httpErr.Code
